COLLDATA("adab","ur",[[1101,"ابو عثمان نہدی رحمہ اللہ سے روایت ہے کہ سیدنا ابو موسی اشعری رضی اللہ عنہ نے ایک غیر مسلم چوہدری (یا راہب) کو خط لکھا تو اسے سلام بھی لکھا۔ ان سے کہا گیا: آپ اس کو سلام کرتے ہیں حالانکہ وہ کافر ہے؟ انہوں نے فرمایا: اس نے مجھے اپنے خط میں سلام لکھا تھا، میں نے اس کا جواب دیا۔","",{"t":"جب ذمی خط میں سلام لکھے تو اس کا جواب دیا جائے","k":"صحیح: مطالب العالیہ(۲۶۵۳)، اتحاف الخیرۃ المہرۃ(۵۲۹۲)، الصحیحہ(۷۰۴)۔ مسدد كما في۔","f":"جس طرح کافر کو زبان سے سلام میں پہل کرنا جائز نہیں اسی طرح خط میں بھی سلام میں پہل کرنا جائز نہیں، البتہ جواباً سلام کہنے کی طرح لکھنا بھی جائز ہے۔","u2":"جناب ابو عثمان نہدی رحمہ اللہ بیان کرتے ہیں کہ سیدنا ابو موسی رضی اللہ عنہ نے ایک کسان کی طرف خط لکھا اور خط میں اسے سلام لکھا، آپ رضی اللہ عنہ سے پوچھا گیا: کیا آپ اسے سلام کرتے ہیں حالانکہ وہ کافر ہے؟ تو انہوں نے فرمایا: اس نے مجھے خط لکھا اور مجھے سلام کیا، لہٰذا میں نے اسے جواب دیا ہے۔"}],[1102,"ابو بصرہ غفاری رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: \"میں کل صبح یہودیوں کی طرف جارہا ہوں، لہٰذا انہیں سلام میں پہل نہ کرنا اور اگر وہ تمہیں سلام کہیں تو جواب میں وعلیکم کہنا۔\" ایک دوسرے طریق سے ابو بصرہ غفاری سے اسی طرح مروی ہے مگر اس میں ہے کہ میں نے نبی صلی اللہ علیہ وسلم سے سنا۔","",{"t":"ذمیوں کو سلام میں پہل نہ کی جائے","k":"صحیح: ابن ابی شیبہ(۲۵۷۶۴)، مسند احمد(۲۷۲۳۵)، نسائی فی الکبری(۱۰۱۴۸)، ابن ماجہ(۳۶۹۹)۔ من حدیث ابی عبدالرحمن الجہنی۔","f":"کافر مسلمان ملک میں رہتا ہو یا کسی کافر ملک میں، اسے سلام میں پہل کرنا جائز نہیں، کیونکہ وہ لائق تکریم و رحمت نہیں۔ اسی طرح اگر کافر راستے میں ملے تو اسے راستہ دینا کہ وہ آسانی سے گزر جائے درست نہیں بلکہ خود \"چوڑے\" ہو کر چلنا چاہیے تاکہ وہ تنگ راستے کی طرف مجبور ہو جائے۔","u2":"سیدنا ابو بصرہ غفاری رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: \"میں کل یہود کی طرف جاؤں گا تم انہیں سلام کرنے میں پہل نہ کرنا جب وہ تمہیں سلام کریں تو جواب میں وعلیکم کہہ دینا۔\" جناب ابن اسحاق رحمہ اللہ سے ایک دوسری سند میں بھی اسی طرح مروی ہے اور اس نے یہ الفاظ زیادہ کہے کہ میں نے نبی صلی اللہ علیہ وسلم سے سنا۔"}],[1103,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: \"اہل کتاب کو سلام میں (کسی صورت بھی) پہل نہ کرو اور انہیں تنگ راستے کی طرف مجبور کر دو۔\"","",{"k":"صحیح: صحیح مسلم(۲۱۶۷)، ابوداؤد(۵۲۰۰)، ترمذی(۱۶۰۲)۔","f":"کافر مسلمان ملک میں رہتا ہو یا کسی کافر ملک میں، اسے سلام میں پہل کرنا جائز نہیں، کیونکہ وہ لائق تکریم و رحمت نہیں۔ اسی طرح اگر کافر راستے میں ملے تو اسے راستہ دینا کہ وہ آسانی سے گزر جائے درست نہیں بلکہ خود \"چوڑے\" ہو کر چلنا چاہیے تاکہ وہ تنگ راستے کی طرف مجبور ہو جائے۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا: \"اہل کتاب کو سلام کرنے میں پہل نہ کرو اور انہیں سب سے تنگ رستے کی طرف جانے پر مجبور کرو۔\""}],[1104,"علقمہ رحمہ اللہ سے روایت ہے، انہوں نے کہا: سیدنا عبداللہ رضی اللہ عنہ نے ذمی چوہدریوں کو اشارے سے سلام کیا۔","",{"t":"ذمی کو اشارے سے سلام کرنا","k":"صحیح: ابن ابی شیبہ(۲۵۸۶۶)، الصحیحہ(۷۰۴)۔","f":"مطلب یہ ہے کہ سلام میں پہل کرنا جائز ہے، تاہم اشارے سے کہنا کہ کیا حال ہے وغیرہ جائز ہے۔ دوسری روایت سے معلوم ہوا کہ کافروں کے سلام کا جواب بھی سوچ سمجھ کر دینا چاہیے کہ جو وہ کہیں وہی انہیں لوٹا دینا چاہیے۔","u2":"جناب علقمہ رحمہ اللہ کہتے ہیں کہ سیدنا عبداللہ رضی اللہ عنہ نے غیر مسلم کسانوں کو اشارے سے سلام کیا تھا۔"}],[1105,"سیدنا انس رضی اللہ عنہ سے روایت ہے، انہوں نے کہا کہ ایک یہودی نبی صلی اللہ علیہ وسلم کے پاس سے گزرا تو اس نے کہا: السام علیکم (تمہیں موت آئے) صحابہ کرام نے سلام کا جواب دیا تو نبی صلی اللہ علیہ وسلم نے فرمایا: \"اس نے تو السام علیکم کہا ہے۔\" یہودی کو پکڑا گیا تو اس نے اعتراف کرلیا۔ آپ نے فرمایا: \"تم بھی اس کے جواب میں ایسے ہی کہو۔\"","",{"k":"صحیح: ترمذی(۳۳۰۱)، صحیح مسلم(۲۱۶۳)، ابوداؤد(۵۲۰۷)، نسائی فی الکبری(۱۰۱۴۷)، ابن ماجہ(۳۶۹۷)۔ مختصرا۔","f":"مطلب یہ ہے کہ سلام میں پہل کرنا جائز ہے، تاہم اشارے سے کہنا کہ کیا حال ہے وغیرہ جائز ہے۔ دوسری روایت سے معلوم ہوا کہ کافروں کے سلام کا جواب بھی سوچ سمجھ کر دینا چاہیے کہ جو وہ کہیں وہی انہیں لوٹا دینا چاہیے۔","u2":"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ ایک یہودی نبی صلی اللہ علیہ وسلم کے پاس سے گزرا، اس نے کہا: السام علیکم (تمہیں موت پڑے) آپ صلی اللہ علیہ وسلم کے صحابہ نے اسے جواب میں السلام کہا تو آپ صلی اللہ علیہ وسلم نے فرمایا: اس یہودی نے السام علیکم کہا ہے۔ چنانچہ یہودی کو پکڑا گیا تو اس نے اس بات کا اعتراف کر لیا آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم اس پر وہی لوٹاؤ جو اس نے کہا ہے۔\""}],[1106,"سیدنا عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب یہودیوں میں سے کوئی تمہیں سلام کہتا ہے تو وہ کہتا ہے: السام علیک (تمہیں موت آئے) تم بھی جواب میں وعلیک (تجھے موت پڑے) کہا کرو۔\"","",{"t":"ذمیوں کو سلام کا جواب کیسے دیا جائے؟","k":"صحیح: صحیح بخاری(۶۲۵۷)، صحیح مسلم(۲۱۶۴)، ابوداؤد(۵۲۰۶)، ترمذی(۱۶۰۳)، نسائی فی الکبری(۱۰۱۳۸)۔","f":"اس سے معلوم ہوا کہ یہود و نصاری کو سلام کرنے میں پہل نہیں کرنی چاہیے۔ اسی طرح ہر کافر کو وہ مشرک ہو یا اہل کتاب سلام کا جواب دینا چاہیے تاہم وعلیکم پر اکتفا کرنا چاہیے۔","u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بے شک جب یہود میں سے تمہیں کوئی سلام کرتا ہے تو وہ کہتا ہے: السام علیك، لہٰذا تم بھی جواب میں وعلیك کہو۔\""}],[1107,"سیدنا ابن عباس رضی اللہ عنہما سے روایت ہے، انہوں نے کہا: یہودی، عیسائی اور مجوسی ہر ایک کو سلام کا جواب دو کیونکہ ارشاد باری تعالی ہے: جب تمہیں تحفہ سلام پیش کیا جائے تو اس کا اچھے اور بہتر طریقے سے جواب دو یا اتنا ہی لوٹا دو۔","",{"k":"حسن: ابن ابی شیبہ(۲۵۷۶۵)، ابن ابی الدنیا فی الصمت(۲۰۷)، ابن ابی حاتم فی تفسیرہ(۵۷۲۹)، ابو یعلی(۱۵۲۷)، الصحیحہ(۲۲۹/۲)۔","f":"اس سے معلوم ہوا کہ یہود و نصاری کو سلام کرنے میں پہل نہیں کرنی چاہیے۔ اسی طرح ہر کافر کو وہ مشرک ہو یا اہل کتاب سلام کا جواب دینا چاہیے تاہم وعلیکم پر اکتفا کرنا چاہیے۔","u2":"سیدنا ابن عباس رضی اللہ عنہ فرماتے ہیں: سلام کا جواب دو خواہ یہودی ہو، عیسائی ہو یا مجوسی ہو یہ اس لیے کہ بے شک اللہ تعالی فرماتا ہے: ﴿وَإِذَا حُيِّيْتُمْ بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا﴾ \"اور جب تمہیں سلامتی کی کوئی دعا دی جائے تو تم اس سے اچھی سلامتی کی دعا دو یا جواب میں وہی کہہ دو۔\""}],[1108,"سیدنا اسامہ بن زید رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم ایک گدھے پر سوار ہوئے جس کے کجاوے پر فدک کی بنی ہوئی چادر تھی، آپ نے اسامہ بن زید کو پیچھے بٹھایا۔ آپ سعد بن عبادہ رضی اللہ عنہ کی عیادت کے لیے تشریف لے گئے، یہاں تک کہ آپ ایک مجلس کے پاس سے گزرے جس میں عبداللہ بن ابی ابن سلول بھی تھا، یہ اس اللہ کے دشمن کے اظہار اسلام سے پہلے کا واقعہ ہے، مجلس میں مسلمان، مشرک اور بت پرست ملے جلے تھے۔ آپ نے انہیں سلام کہا۔","",{"t":"مسلمانوں اور مشرکوں کی ملی جلی مجلس کو سلام کہنا","k":"صحیح: صحیح بخاری(۶۲۰۷)، صحیح مسلم(۱۷۹۸)، نسائی فی الکبری(۷۴۶۰)۔","f":"اس سے معلوم ہوا کہ جہاں کافر اور مسلمان ملے جلے ہوں وہاں سلام میں پہل کرنا جائز ہے۔\nگدھے پر سواری کرنا کوئی عیب نہیں، نیز اگر جانور متحمل ہو تو اس پر ایک سے زائد آدمی سوار ہو سکتے ہیں۔\nسفر کر کے یا سوار ہو کر کسی کی عیادت کے لیے جانا جائز ہے۔","u2":"سیدنا اسامہ بن زید رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم ایک گدھے پر سوار ہوئے جس پر فدک کی چادر کے اوپر پالان رکھی ہوئی تھی، آپ نے سیدنا اسامہ بن زید رضی اللہ عنہ کو اپنے پیچھے بٹھا لیا، آپ سیدنا سعد بن عبادہ رضی اللہ عنہ کی عیادت کے لیے تشریف لے جارہے تھے، راستے میں آپ کا گزر ایک ایسی مجلس سے ہوا جس میں عبداللہ بن ابی ابن سلول بھی تھا یہ واقعہ عبداللہ بن ابی کے اسلام لانے سے پہلے کا ہے، اس مجلس میں مسلمان، مشرکین اور بت پرست سب ملے جلے بیٹھے ہوئے تھے، پس آپ نے انہیں سلام کیا۔"}],[1109,"سیدنا عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ روم کے بادشاہ ہرقل نے سیدنا ابو سفیان رضی اللہ عنہ کو بلایا، پھر اس نے رسول اللہ صلی اللہ علیہ وسلم کا وہ خط منگوایا جو اس کی طرف بھیجا گیا تھا۔ یہ خط آپ نے سیدنا دحیہ کلبی رضی اللہ عنہ کو بصری کے حاکم کو دینے کا حکم دیا تو اس نے ہرقل کو پہنچایا اس نے اسے پڑھا، اس میں تھا: بسم اللہ الرحمن الرحیم۔ اللہ کے بندے اور رسول محمد کی طرف سے روم کے بادشاہ ہرقل کی طرف، سلام ہو اس پر جس نے ہدایت کی پیروی کی۔ بلاشبہ میں تم کو اسلام کی طرف بلاتا ہوں۔ اسلام قبول کرلو، سلامت رہو گے اور اللہ تعالی تمہیں اس کا دوہرا اجر عطا فرمائے گا اور اگر تم نے انکار کیا تو رعایا کا گناہ بھی تم پر ہوگا۔ اور اے اہل کتاب آؤ ایک ایسی بات کی طرف جو ہمارے اور تمہارے درمیان برابر ہے۔ تم اس کے گواہ رہو گے کہ ہم مسلمان ہیں۔","",{"t":"اہل کتاب کی طرف خط کس طرح لکھا جائے","k":"صحیح: صحیح بخاری(۷)، صحیح مسلم(۱۷۷۳)۔","f":"رسول اکرم صلی اللہ علیہ وسلم نے تمام بادشاہوں کو خطوط لکھے تو روم کے بادشاہ ہرقل کو بھی خط لکھا۔ اس نے ابو سفیان رضی اللہ عنہ کے متعلق پوچھا جو ابھی مسلمان نہیں ہوئے تھے اور تجارت کی غرض سے شام گئے ہوئے تھے۔\nاس میں خط لکھنے کا ادب بھی ذکر ہوا ہے کہ پہلے بسم اللہ لکھی جائے اور خط لکھنے والا اپنا نام اور عہدہ لکھے اور اس کے بعد جس کی طرف خط لکھا جا رہا ہے اس کا نام لکھا جائے نیز خط اگر کافر کے نام ہو تو سلام میں یہ انداز اختیار کیا جائے کہ سلام ہو اس پر جو ہدایت کی پیروی کرے۔\nمسلمان کے لیے یہ جائز نہیں ہے کہ وہ کافر سے محبت کے خطوط لکھے بلکہ مبنی بر دعوت خطوط ہونے چاہئیں۔","u2":"سیدنا عبداللہ بن عباس رضی اللہ عنہ بیان کرتے ہیں کہ روم کے بادشاہ ہرقل نے ابو سفیان بن حرب رضی اللہ عنہ کی طرف پیغام بھیجا پھر رسول اللہ صلی اللہ علیہ وسلم کا وہ خط منگوایا جو آپ نے اپنے صحابی دحیہ کلبی رضی اللہ عنہ کے ذریعہ بصری کے گورنر کی طرف بھیجا تھا اس نے وہ ہرقل کو پہنچا دیا تھا، ہرقل نے اسے پڑھا اس میں لکھا ہوا تھا: \"شروع اللہ کے نام سے جو بڑا مہربان، بے حد رحم والا ہے، اللہ کے بندے اور اس کے رسول محمد صلی اللہ علیہ وسلم کی طرف سے عظیم روم ہرقل کی طرف، سلام ہو اس شخص پر جس نے ہدایت کی پیروی کی، اما بعد! میں تمہیں اسلام کی طرف بلاتا ہوں اسلام قبول کرلے تو سلامت رہے گا اللہ تجھے دوہرا اجر دے گا اور اگر تو نے منہ پھیرا تو بے شک تجھ پر تیری ساری رعایا کا گناہ بھی ہوگا۔ اے اہل کتاب! ایسی بات کی طرف آؤ جو ہمارے اور تمہارے درمیان یکساں ہے کہ ہم اللہ تعالی کے سوا کسی کی عبادت نہ کریں اور اس کے ساتھ کسی کو شریک نہ ٹھہرائیں اور ہم میں سے کوئی بھی اللہ تعالی کو چھوڑ کر کسی کو رب نہ قرار دے پھر اگر وہ لوگ اعراض کریں تو تم کہہ دو گواہ رہو بے شک ہم مسلمان ہیں۔\""}],[1110,"سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ کچھ یہودیوں نے نبی صلی اللہ علیہ وسلم کو سلام کیا تو کہا: السام علیکم۔ آپ نے فرمایا: \"وعلیکم،\" سیدہ عائشہ رضی اللہ عنہا کو بہت غصہ آیا تو انہوں نے کہا: (اللہ کے رسول!) آپ نے سنا نہیں جو انہوں نے کہا؟ آپ نے فرمایا: \"کیوں نہیں میں نے سنا ہے اور وہ الفاظ انہی پر لوٹا دیے ہیں۔ ہماری دعا ان کے خلاف قبول ہوتی ہے اور ان کی ہمارے خلاف کی گئی دعا قبول نہیں ہوتی۔\"","",{"t":"جب کافر السام علیکم کہے تو؟","k":"صحیح: صحیح مسلم(۲۱۶۶)۔","f":"کافر السام علیکم کہیں یا السلام علیکم، ان کے جواب میں وعلیکم پر اکتفا کرنا چاہیے۔ مزید تفصیل میں جانے کی اور بحث کی ضرورت نہیں۔ اگر کسی علاقے میں پہل کرنے کی ضرورت ہو تو سلام کے بجائے اشارے اور دیگر کلمات پر اکتفا کرنا چاہیے۔","u2":"سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ یہودیوں میں سے کچھ لوگوں نے نبی صلی اللہ علیہ وسلم کو سلام کیا تو کہا: السام علیکم، آپ صلی اللہ علیہ وسلم نے جواب میں فرمایا: وعلیکم سیدہ عائشہ رضی اللہ عنہا نے غصے میں آکر کہا: کیا آپ نے نہیں سنا جو کچھ انہوں نے کہا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ہاں میں نے سنا ہے اور میں نے وہ الفاظ انہیں پر لوٹا دیے، ہماری بدعا ان کے بارے میں قبول ہوگی اور ان کی بدعا ہمارے بارے میں قبول نہیں ہوگی۔"}],[1111,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: \"جب تم مشرکوں سے راستے میں ملو تو انہیں سلام میں پہل نہ کرو اور انہیں تنگ ترین راستے کی طرف مجبور کر دو۔\"","",{"t":"اہل کتاب کو بہت تنگ راستے کی طرف مجبور کیا جائے","k":"شاذ بہذا السیاق فی الشطر الاول: مسند احمد(۷۵۶۷)، عبدالرزاق(۹۸۳۷)، طبرانی فی الاوسط(۶۳۵۸)، بیہقی فی شعب(۹۳۸۱)، الصحیحہ(۷۰۴)۔","f":"مطلب یہ ہے کہ ان کی تکریم کی خاطر راستہ چھوڑنے کی ضرورت نہیں بلکہ انہیں ان کے کافر ہونے کا احساس دلانا ضروری ہے۔ نیز یہ روایت ان الفاظ کے ساتھ شاذ ہے اور محفوظ وہ الفاظ ہیں جو رقم ۱۱۰۳ میں گزرے ہیں۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: \"جب تم راستے میں مشرکین سے ملاقات کرو تو انہیں سلام کرنے میں پہل نہ کرو اور انہیں تنگ ترین رستے کی طرف جانے پر مجبور کر دو۔\""}],[1112,"سیدنا عقبہ بن عامر جہنی رضی اللہ عنہ سے روایت ہے کہ وہ ایک ایسے شخص کے پاس سے گزرے جس کی شکل و صورت مسلمانوں والی تھی۔ اس نے سلام کہا تو سیدنا عقبہ رضی اللہ عنہ نے جواب دیا: وعلیک ورحمۃ اللہ وبرکاتہ۔ ان کے غلام نے اسے کہا: وہ شخص تو عیسائی ہے۔ سیدنا عقبہ رضی اللہ عنہ اٹھ کر اس آدمی کے پیچھے گئے اور ڈھونڈ کر فرمایا: اللہ کی رحمت اور اس کی برکت تو اہل ایمان پر ہے لیکن اللہ تعالی تیری عمر دراز کرے اور تجھے مال اور اولاد زیادہ دے۔","",{"t":"ذمی کے لیے کس طرح دعا کرے","k":"حسن: بیہقی فی الکبری(۲۰۳/۹)، ابن عساکر فی تاریخہ(۱۰۲/۶۷)، مزی فی تہذیب الکمال(۱۳۳/۲۴)۔","f":"ان روایات سے معلوم ہوا کہ کافر اگر واضح الفاظ میں سلام کہیں یا کوئی دعا دیں تو اس کا جواب دیا جا سکتا ہے۔ تاہم عمومی حالت میں وعلیکم پر اکتفا کرنا ہی زیادہ بہتر ہے۔ اسی طرح کسی کافر کو مرحوم کہنا بھی درست نہیں۔","u2":"جناب یحیی بن ابی عمرو شیبانی رحمہ اللہ اپنے والد سے، وہ سیدنا عقبہ بن عامر جہنی رضی اللہ عنہ سے روایت کرتے ہیں کہ وہ ایک آدمی کے پاس سے گزرے جس کی شکل و صورت مسلمانوں جیسی تھی۔ اس نے سلام کیا تو آپ رضی اللہ عنہ نے اس کے جواب میں وعلیك ورحمة اللہ وبرکاتہ کہا، آپ کے غلام نے آپ سے کہا کہ یہ تو عیسائی ہے، چنانچہ سیدنا عقبہ رضی اللہ عنہ کھڑے ہوئے اور اس کے پیچھے گئے، یہاں تک کہ اسے پالیا اور اس سے فرمایا: بے شک اللہ تعالی کی رحمت اور اس کی برکتیں تو ایمان والوں پر ہیں لیکن اللہ تعالی تیری زندگی لمبی کرے اور تیرے مال اور اولاد میں کثرت کرے۔"}],[1113,"سیدنا ابن عباس رضی اللہ عنہما سے روایت ہے، انہوں نے کہا: اگر فرعون مجھے کہے کہ اللہ تجھے برکت دے تو میں اسے بھی کہوں گا: اور تجھے بھی حالانکہ فرعون مر چکا ہے۔","",{"k":"صحیح: ابن ابی الدنیا فی الصمت(۲۰۹)، طبرانی فی الکبیر(۲۶۲/۱۰)، ابو نعیم فی الحلیہ(۳۲۲/۱)، الصحیحہ(۳۲۹/۲)۔","f":"ان روایات سے معلوم ہوا کہ کافر اگر واضح الفاظ میں سلام کہیں یا کوئی دعا دیں تو اس کا جواب دیا جا سکتا ہے۔ تاہم عمومی حالت میں وعلیکم پر اکتفا کرنا ہی زیادہ بہتر ہے۔ اسی طرح کسی کافر کو مرحوم کہنا بھی درست نہیں۔","u2":"سیدنا ابن عباس رضی اللہ عنہ فرماتے ہیں: اگر فرعون بھی مجھے کہے: بَارَكَ اللہُ فِیكَ (اللہ تجھ میں برکت دے تو) میں جواب میں کہوں گا: وَفِیكَ (اور تجھ میں بھی) حالانکہ فرعون تو مر چکا ہے۔"}],[1114,"سیدنا ابو موسی رضی اللہ عنہ سے روایت ہے، انہوں نے فرمایا: یہودی نبی صلی اللہ علیہ وسلم کے سامنے چھینک مارتے، اس امید سے کہ آپ انہیں یرحمکم اللہ کہیں لیکن آپ فرماتے: اللہ تمہیں ہدایت دے اور تمہارے معاملات کی اصلاح کرے۔","",{"k":"صحیح: ابوداؤد(۵۰۳۸)، ترمذی(۲۷۳۹)، نسائی فی الکبری(۹۹۹۰)۔","f":"ان روایات سے معلوم ہوا کہ کافر اگر واضح الفاظ میں سلام کہیں یا کوئی دعا دیں تو اس کا جواب دیا جا سکتا ہے۔ تاہم عمومی حالت میں وعلیکم پر اکتفا کرنا ہی زیادہ بہتر ہے۔ اسی طرح کسی کافر کو مرحوم کہنا بھی درست نہیں۔","u2":"سیدنا ابو موسی رضی اللہ عنہ بیان کرتے ہیں کہ یہودی نبی کریم صلی اللہ علیہ وسلم کے پاس اس امید سے چھینکا کرتے تھے کہ آپ صلی اللہ علیہ وسلم انہیں يَرْحَمُكُمُ اللہ کہیں مگر آپ صلی اللہ علیہ وسلم ان کے لیے \"يَهْدِيكُمُ اللہُ وَيُصْلِحُ بَالَكُمْ\" (اللہ تعالی تمہیں ہدایت دے اور تمہارے حال کی اصلاح کرے)۔"}],[1115,"عبدالرحمن بن محمد رحمہ اللہ سے روایت ہے، انہوں نے کہا کہ سیدنا ابن عمر رضی اللہ عنہما ایک عیسائی کے پاس سے گزرے تو اسے سلام کہا اور اس نے جواب بھی دیا۔ بعد ازاں انہیں بتایا گیا کہ وہ تو عیسائی ہے۔ جب انہیں یہ علم ہوا تو اس کے پاس گئے اور فرمایا: میرا سلام مجھے واپس کرو۔","",{"t":"اگر عیسائی کو لا علمی میں سلام کہہ لیا تو؟","k":"حسن: عبدالرزاق(۱۹۴۵۸)، بیہقی فی شعب الایمان(۸۹۰۶)، الارواء(۱۲۷۴)۔","f":"سیدنا ابن عمر رضی اللہ عنہما کا مقصد اس بات کا اظہار تھا کہ کافر ابتداے سلام کا مستحق نہیں ہوسکتا کیونکہ یہ صرف مسلمان کا حق ہے کیونکہ کافر مشرک سلامتی اور خیر و برکت کے مستحق نہیں ہوسکتے۔","u2":"جناب عبدالرحمن رحمہ اللہ بیان کرتے ہیں کہ سیدنا ابن عمر رضی اللہ عنہ ایک عیسائی کے پاس سے گزرے تو آپ نے اسے سلام کیا، اس نے سلام کا جواب دیا، پھر آپ کو بتایا گیا کہ وہ تو عیسائی تھا۔ چنانچہ جب آپ کو پتا چلا تو واپس اس کے پاس آئے اور فرمایا: میرا سلام مجھے واپس کرو۔"}],[1116,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے اس سے فرمایا: \"جبریل تمہیں سلام کہتے ہیں۔\" سیدہ عائشہ رضی اللہ عنہا نے فرمایا: اور ان پر بھی سلام اور اللہ کی رحمت ہو۔","",{"t":"جب کسی نے کہا کہ فلاں شخص تجھے سلام کہتا ہے","k":"صحیح: صحیح بخاری(۳۷۶۸)، صحیح مسلم(۲۴۴۷)۔","f":"اس سے معلوم ہوا کہ غائبانہ سلام کہنا جائز ہے اور اس کا جواب دینا بھی مسنون ہے۔ اس کی تفصیل حدیث ۸۲۷ کے تحت گزر چکی ہے کہ پیغام پہنچانے والے اور سلام کہنے والے دونوں کو سلامتی کی دعا دی جائے، یعنی علیک وعلیہ السلام۔","u2":"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ نبی صلی اللہ علیہ وسلم نے ان سے فرمایا: \"جبریل علیہ السلام تجھے سلام کہتا ہے۔\" تو انہوں نے کہا: وعلیہ السلام ورحمة اللہ۔ (اور اس پر بھی سلام اور اللہ کی رحمت ہو)"}],[1117,"سیدنا ابن عباس رضی اللہ عنہما سے روایت ہے، انہوں نے فرمایا: میں خط کا جواب دینا سلام کے جواب کی طرح ضروری سمجھتا ہوں۔","",{"t":"خط کا جواب دینا","k":"حسن: ابن ابی شیبہ(۲۶۳۶۹)، ابن الجعد(۲۳۹۹)، بیہقی فی شعب الایمان(۹۰۹۷)۔","f":"سیدنا ابن عباس رضی اللہ عنہما کا مقصد یہ ہے کہ جس طرح سلام کا جواب دینا فرض ہے اسی طرح خط کا جواب دینا بھی واجب ہے۔","u2":"سیدنا ابن عباس رضی اللہ عنہ فرماتے ہیں: بے شک میں تو خط کے جواب کو سلام کے جواب کی طرح ضروری سمجھتا ہوں۔"}],[1118,"سیدہ عائشہ بنت طلحہ رحمہا اللہ سے روایت ہے کہ میں نے سیدہ عائشہ رضی اللہ عنہا سے عرض کیا اور میں ان کی زیر پرورش تھی۔ ان کے پاس دنیا کے اطراف و اکناف سے لوگ آتے تھے۔ بزرگ حضرات باری باری میرے پاس آتے کیونکہ انہیں معلوم تھا کہ میں ان کی خادمہ ہوں اور نوجوان طالب علم بہنوں کی طرح میرا قصد کرتے اور مجھے ہدیے ارسال کرتے اور مختلف شہروں سے مجھے خط لکھتے تو میں سیدہ عائشہ رضی اللہ عنہا کو بتاتی۔ خالہ جان یہ فلاں کا خط اور تحفہ ہے تو سیدہ عائشہ رضی اللہ عنہا مجھے فرماتیں: بیٹی! خط کا جواب دے دو اور ہدیے کا بدلہ بھی دے دو اور اگر تمہارے پاس عطیے کا بدلہ دینے کے لیے کچھ نہ ہو تو میں دے دیتی ہوں۔ وہ کہتی ہیں کہ پھر وہ مجھے دے دیتیں۔","",{"t":"عورتوں کے نام خط لکھنا اور ان کا جواب دینا","k":"حسن۔","f":"اس سے معلوم ہوا کہ علمی مقاصد کے لیے خواتین سے خط و کتابت بھی جائز ہے بشرطیکہ کسی فتنے کا اندیشہ نہ ہو۔ اسی طرح خواتین جواب بھی دے سکتی ہیں۔\nاس روایت سے قرون اولی میں حصول علم کے شوق اور اہل علم کی اہمیت اور عزت و توقیر کا پتہ بھی چلتا ہے۔\nعلما اور اساتذہ کے گھر تحائف بھیجنا حسن امر ہے اور اہل علم کو بھی چاہیے کہ وہ بدلے میں تحائف دیں۔","u2":"عائشہ بنت طلحہ رحمہا اللہ بیان کرتی ہیں کہ میں نے سیدہ عائشہ رضی اللہ عنہا سے کہا جس وقت میں ان کی پرورش میں تھی، لوگ ان کے پاس ہر شہر سے آتے رہتے تھے، سیدہ عائشہ رضی اللہ عنہا کے پاس رہنے کی وجہ سے بوڑھے تو مجھے بیٹی کہتے اور نوجوان مجھے اپنی بہن کہتے تھے۔ چنانچہ وہ میرے پاس ہدیہ بھیجتے رہتے اور مجھے مختلف شہروں سے خط بھی آتے رہتے تھے، میں سیدہ عائشہ سے کہتی: اے خالہ! یہ فلاں کا خط ہے اور اس کا ہدیہ ہے تو سیدہ عائشہ مجھے فرماتیں: اے بیٹی! اس کا جواب دو اور اس کا بدلہ دو، اگر تیرے پاس بدلہ دینے کے لیے کچھ نہیں تو میں تجھے دے دیتی ہوں۔ بنت طلحہ رحمہا اللہ کہتی ہے کہ پھر وہ مجھے دے بھی دیا کرتی تھیں۔"}],[1119,"سیدنا عبداللہ بن دینار رحمہ اللہ سے روایت ہے کہ سیدنا عبداللہ بن عمر رضی اللہ عنہما نے عبد الملک بن مروان کی بیعت کی تو انہیں لکھا: بسم اللہ الرحمن الرحیم امیر المومنین عبدالملک کے نام عبداللہ بن عمر کی طرف سے۔ آپ پر سلام، چنانچہ میں اللہ کی تعریف کرتا ہوں جس کا کوئی شریک نہیں اور اقرار کرتا ہوں کہ حسب استطاعت آپ کے احکام سنوں گا اور اطاعت بجالاؤں گا جو اللہ تعالی اور اس کے رسول صلی اللہ علیہ وسلم کے بتائے ہوئے طریقوں کے مطابق ہوں گے۔","",{"t":"خط کی ابتدا کیسے کی جائے","k":"صحیح: صحیح بخاری(۷۲۰۵)۔","f":"اس سے معلوم ہوا کہ خط کا آغاز بسم اللہ الرحمن الرحیم سے کرنا چاہیے اور اس کے بعد آدمی کو اختیار ہے کہ پہلے اپنا تعارف کروائے جس طرح رسول اکرم صلی اللہ علیہ وسلم خط لکھتے تھے اور یہ زیادہ بہتر ہے یا پہلے مخاطب کا نام لکھے اور ایسا کرنا بھی جائز ہے جیسا کہ سیدنا ابن عمر رضی اللہ عنہما نے کیا۔","u2":"جناب عبداللہ بن دینار رحمہ اللہ بیان کرتے ہیں کہ سیدنا عبداللہ بن عمر رضی اللہ عنہ نے عبدالملک بن مروان رحمہ اللہ کو ان کی بیعت کرنے کا خط یوں لکھا: بسم اللہ الرحمن الرحیم، یہ خط عبداللہ بن عمر رضی اللہ عنہ کی طرف سے امیر المومنین عبدالملک کی طرف ہے آپ پر سلام ہو، میں آپ کے سامنے اللہ کی تعریف کرتا ہوں جس کے سوا کوئی معبود نہیں اور میں اللہ اور اس کے رسول کے طریقے کے مطابق جس قدر مجھ سے ہو سکا آپ کے لیے سمع و طاعت کا اقرار کرتا ہوں۔"}],[1120,"سیدنا زید بن اسلم رحمہ اللہ سے روایت ہے کہ مجھے میرے والد نے سیدنا ابن عمر رضی اللہ عنہما کی طرف بھیجا۔ میں نے دیکھا وہ لکھ رہے تھے: بسم اللہ الرحمن الرحیم اما بعد۔","",{"t":"اما بعد کا بیان","k":"صحیح: ابن ابی شیبہ(۲۵۸۵۱)، ابن سعد فی الطبقات(۱۶۱/۴)۔","f":"مطلب یہ ہے کہ جس طرح خطبہ میں اما بعد کا لفظ استعمال کیا جاسکتا ہے اسی طرح تحریر میں بھی اما بعد کا لفظ استعمال کرنا مسنون ہے۔","u2":"جناب زید بن اسلم رحمہ اللہ بیان کرتے ہیں کہ میرے والد نے مجھے سیدنا ابن عمر رضی اللہ عنہ کے پاس بھیجا میں نے انہیں \"بسم اللہ الرحمن الرحیم\" کے بعد \"أما بعد\" لکھتے ہوئے دیکھا۔"}],[1121,"ہشام بن عروہ رحمہ اللہ سے روایت ہے کہ میں نے نبی صلی اللہ علیہ وسلم کے خطوط میں سے کئی خط دیکھے کہ جب کوئی بات ختم ہوتی وہاں اما بعد لکھا ہوتا۔","",{"k":"صحیح: ابن ابی شیبہ(۲۵۸۴۸)، ابن ابی شیبہ(۲۵۸۵۲)، الارواء(۳۸/۱)۔","f":"مطلب یہ ہے کہ جس طرح خطبہ میں اما بعد کا لفظ استعمال کیا جاسکتا ہے اسی طرح تحریر میں بھی اما بعد کا لفظ استعمال کرنا مسنون ہے۔","u2":"جناب ہشام بن عروہ رحمہ اللہ کہتے ہیں کہ میں نے نبی کریم صلی اللہ علیہ وسلم کے خطوط میں سے کئی خطوط کو دیکھا جہاں کوئی بات ختم ہوتی وہیں \"اما بعد\" لکھا ہوتا۔"}],[1122,"سیدنا زید بن ثابت رضی اللہ عنہ سے روایت ہے کہ انہوں نے یہ خط لکھا: بسم اللہ الرحمن الرحیم۔ اللہ کے بندے امیر المومنین معاویہ کے نام زید بن ثابت کی طرف سے۔ امیر المومنین آپ پر سلام اور اللہ کی رحمت ہو۔ میں اللہ تعالی کی تعریف کرتا ہوں جس کے سوا کوئی معبود برحق نہیں۔ اما بعد۔","",{"t":"خطوط کی ابتدا بسم اللہ الرحمن الرحیم سے کی جائے","k":"حسن: مالک فی الموطا(۹۰۱)، طبرانی فی الکبیر(۱۳۴/۵)، بیہقی فی الکبری(۲۴۷/۶)۔ فی روایۃ محمد بن الحسن عنہ۔","f":"اس سے معلوم ہوا کہ ہر اچھے کام کا آغاز بسم اللہ الرحمن الرحیم سے کرنا چاہیے۔ یہ خیر و برکت کا ذریعہ ہے۔","u2":"جناب خارجہ بن زید رحمہ اللہ آل زید بن ثابت کے بزرگوں سے روایت کرتے ہیں سیدنا زید بن ثابت رضی اللہ عنہ نے سیدنا معاویہ رضی اللہ عنہ کی طرف یہ خط لکھا \"بسم اللہ الرحمن الرحیم\" یہ خط زید بن ثابت کی طرف سے اللہ کے بندے امیر المومنین معاویہ رضی اللہ عنہ کے لیے ہے، اے امیر المومنین! آپ پر سلام اور اللہ کی رحمت ہو، میں آپ کے سامنے اللہ تعالی کی تعریف کرتا ہوں جس کے سوا کوئی معبود نہیں، اما بعد!"}],[1123,"ابو مسعود جریری رحمہ اللہ سے روایت ہے کہ ایک آدمی نے سیدنا حسن (بصری) رحمہ اللہ سے بسم اللہ پڑھنے کے بارے میں پوچھا تو انہوں نے کہا: یہ خطوط کے شروع میں بھی لکھنی چاہیے۔","",{"k":"صحیح الإسناد عن الحسن وهو البصری۔","f":"اس سے معلوم ہوا کہ ہر اچھے کام کا آغاز بسم اللہ الرحمن الرحیم سے کرنا چاہیے۔ یہ خیر و برکت کا ذریعہ ہے۔","u2":"جناب ابو مسعود جریری رحمہ اللہ کہتے ہیں کہ ایک آدمی نے حسن بصری رحمہ اللہ سے (خط کے شروع میں بسم اللہ الرحمن الرحیم پڑھنے کے متعلق) پوچھا تو انہوں نے فرمایا: یہ خطوط کا ابتدائی حصہ ہے۔"}],[1124,"نافع رحمہ اللہ سے روایت ہے کہ سیدنا ابن عمر رضی اللہ عنہما کو سیدنا معاویہ رضی اللہ عنہ سے کوئی کام تھا۔ انہوں نے خط لکھنے کا ارادہ کیا تو لوگوں نے کہا: ابتدا ان کے نام سے کریں۔ وہ مسلسل اصرار کرتے رہے یہاں تک کہ انہوں نے لکھا: بسم اللہ الرحمن الرحیم معاویہ کی طرف۔","",{"t":"خط کے شروع میں کس کا نام لکھا جائے","k":"صحیح: ابن ابی شیبہ(۲۵۸۸۹)، بیہقی فی الکبری(۱۳۰/۱۰)۔","f":"اس سے معلوم ہوا کہ سیدنا ابن عمر رضی اللہ عنہما کا موقف یہی تھا کہ خط لکھنے والے کو پہلے اپنا نام لکھنا چاہیے، تاہم بعض وجوہات کی بنا پر اس کے برعکس بھی کر لیتے تھے کیونکہ یہ کوئی حلال و حرام والا مسئلہ نہیں۔ بات افضل اور غیر افضل کی ہے۔","u2":"امام نافع رحمہ اللہ کہتے ہیں کہ سیدنا ابن عمر رضی اللہ عنہ کو سیدنا معاویہ رضی اللہ عنہ سے کوئی کام تھا تو انہوں نے ان کی طرف خط لکھنا چاہا لوگوں نے کہا ان کے نام کے ساتھ ابتدا کریں، لوگ برابر یہی کہتے رہے مگر انہوں نے لکھا: بسم اللہ الرحمن الرحیم معاویہ کی طرف۔"}],[1125,"انس بن سیرین رحمہ اللہ سے روایت ہے کہ میں نے ابن عمر رضی اللہ عنہما کے کہنے پر خط لکھا تو انہوں نے فرمایا: یوں لکھو: بسم اللہ الرحمن الرحیم، اما بعد الی فلان یعنی فلاں کے نام۔","",{"k":"صحیح: ابن ابی شیبہ(۲۵۸۸۹)۔","f":"اس سے معلوم ہوا کہ سیدنا ابن عمر رضی اللہ عنہما کا موقف یہی تھا کہ خط لکھنے والے کو پہلے اپنا نام لکھنا چاہیے، تاہم بعض وجوہات کی بنا پر اس کے برعکس بھی کر لیتے تھے کیونکہ یہ کوئی حلال و حرام والا مسئلہ نہیں۔ بات افضل اور غیر افضل کی ہے۔","u2":"جناب انس بن سیرین رحمہ اللہ کہتے ہیں کہ میں نے سیدنا ابن عمر رضی اللہ عنہ کے کہنے پر خط لکھا تو انہوں نے فرمایا: یوں لکھو \"بسم اللہ الرحمن الرحیم، أما بعد! فلاں کی طرف\""}],[1126,"انس بن سیرین رحمہ اللہ سے روایت ہے کہ ایک آدمی نے سیدنا ابن عمر رضی اللہ عنہما کے سامنے خط لکھا: بسم اللہ الرحمن الرحیم، فلاں کے نام۔ سیدنا ابن عمر رضی اللہ عنہما نے اسے منع کر دیا اور فرمایا کہ اس طرح لکھو: بسم اللہ۔ یہ اس کے نام ہے یعنی ہو لکھ کر اس کا نام لکھو۔","",{"k":"صحیح: ابن ابی شیبہ(۲۵۸۳۹)۔","f":"اس سے معلوم ہوا کہ سیدنا ابن عمر رضی اللہ عنہما کا موقف یہی تھا کہ خط لکھنے والے کو پہلے اپنا نام لکھنا چاہیے، تاہم بعض وجوہات کی بنا پر اس کے برعکس بھی کر لیتے تھے کیونکہ یہ کوئی حلال و حرام والا مسئلہ نہیں۔ بات افضل اور غیر افضل کی ہے۔","u2":"جناب انس بن سیرین رحمہ اللہ بیان کرتے ہیں کہ ایک آدمی نے سیدنا ابن عمر رضی اللہ عنہ کے سامنے یوں خط لکھا \"بسم اللہ الرحمن الرحیم فلاں کے لیے\" سیدنا ابن عمر رضی اللہ عنہ نے اسے لفظ \"فلاں کے لیے\" لکھنے سے منع فرمایا اور کہا کہ \"بسم اللہ الرحمن الرحیم\" لکھو یہ (خط) تو اس کے لیے ہے۔"}],[1127,"سیدنا زید بن ثابت رضی اللہ عنہ سے مروی ہے کہ انہوں نے یوں خط لکھا: اللہ کے بندے امیر المومنین معاویہ کے نام زید بن ثابت کی طرف سے۔ امیر المومنین آپ پر سلام اور اللہ کی رحمت ہو، میں اس اللہ کی تعریف کرتا ہوں جس کے سوا کوئی معبود برحق نہیں۔ اما بعد۔","",{"k":"حسن: حدیث ۱۱۲۲۔","f":"یہ حدیث پہلے گزر چکی ہے۔ اس کا مطلب بھی یہی ہے کہ مرسل الیہ کا نام پہلے لکھنا جائز ہے۔","u2":"جناب خارجہ بن زید رحمہ اللہ آل زید بن ثابت کے بزرگوں سے روایت کرتے ہیں سیدنا زید بن ثابت رضی اللہ عنہ نے یہ خط لکھا: \"زید بن ثابت کی طرف سے اللہ کے بندے امیر المومنین معاویہ رضی اللہ عنہ کے لیے: اے امیر المومنین! آپ پر سلام اور اللہ کی رحمت ہو، آپ رضی اللہ عنہ کے سامنے میں اس اللہ کی تعریف کرتا ہوں جس کے سوا کوئی معبود نہیں، اما بعد!\""}],[1128,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: بنی اسرائیل کا ایک آدمی تھا۔ پھر لمبی حدیث ذکر کی۔ اور اس نے اپنے ساتھی کی طرف یوں لکھا: فلاں کی طرف سے فلاں کے نام۔","",{"k":"ضعیف۔","f":"اس روایت کی سند عمر بن ابی سلمہ کی وجہ سے ضعیف ہے۔ یہ روایت صحیح بخاری میں معلق اور ایک دوسری سند سے موصول دونوں انداز میں موجود ہے۔ (دیکھیں فتح الباری: ۴/۲۷۰، ۳/۳۶۳۔ بخاری: ۲۰۶۳)","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا: \"بے شک بنی اسرائیل میں سے ایک آدمی نے\" اور آپ صلی اللہ علیہ وسلم نے مکمل حدیث بیان کی (جس میں یہ بھی تھا کہ اس نے اپنے ساتھی کو یوں خط لکھا فلاں کی طرف سے فلاں کے لیے)۔"}],[1129,"سیدنا محمود بن لبید رضی اللہ عنہ سے روایت ہے کہ غزوہ خندق کے روز جب سیدنا سعد رضی اللہ عنہ کی رگ کٹ گئی اور ان کی تکلیف زیادہ بڑھ گئی تو انہوں نے انہیں ایک رفیدہ نامی عورت پر زخمیوں کا علاج کرتی تھی جو نبی صلی اللہ علیہ وسلم جب ان کے پاس سے گزرتے تو پوچھتے: \"تیری شام کس حال میں ہوئی؟\" اور صبح حال دریافت کرتے تو پوچھتے: \"صبح کس حال میں ہوئی؟\" تو وہ اپنا حال بتا دیتے۔","",{"t":"صبح کس حال میں ہوئی؟ کہنے کا بیان","k":"صحیح: التاریخ الاوسط(۱/۲۲)، طبقات ابن سعد(۳/۴۲۷)، الصحیحہ(۱۱۵۸)۔","f":"کسی کی خیریت دریافت کرنا مسنون ہے اور اس کے لیے یہ انداز اختیار کرنا کہ تم نے صبح کس حال میں کی؟ جائز ہے۔ مریض اگر حقیقت حال بتائے گا تو یہ شکوہ نہیں ہوگا۔ اسی طرح کسی دوسرے شخص سے بھی بیمار کا حال دریافت کیا جا سکتا ہے۔\nاس حدیث سے شیعہ کے مذعومہ عقیدہ خلیفہ بلا فصل کی تردید ہوتی ہے۔ اگر سیدنا علی رضی اللہ عنہ خلیفہ بلا فصل ہوتے تو لوگوں کے سامنے ضرور اس کا اظہار کرتے۔","u2":"سیدنا محمود بن لبید رضی اللہ عنہ بیان کرتے ہیں کہ غزوہ خندق کے دن جب سیدنا سعد رضی اللہ عنہ کے بازو کی ایک رگ زخمی ہوئی تو ان کی حالت خراب ہوگئی لوگوں نے انہیں ایک عورت کے ہاں پہنچا دیا جسے رفیدہ رضی اللہ عنہا کہا جاتا تھا اور وہ زخمیوں کا علاج کیا کرتی تھی، نبی صلی اللہ علیہ وسلم جب بھی سیدنا سعد رضی اللہ عنہ کے پاس سے گزرتے تھے تو فرماتے: تو نے شام کس حال میں کی؟ اور جب صبح کو جاتے تو فرماتے: تو نے صبح کس حال میں کی؟ وہ اپنا حال بتا دیتے۔"}],[1130,"سیدنا ابن عباس رضی اللہ عنہما سے روایت ہے کہ سیدنا علی رضی اللہ عنہ نبی صلی اللہ علیہ وسلم کی اس بیماری میں جس میں آپ نے وفات پائی، آپ کے پاس سے باہر آئے تو لوگوں نے پوچھا: ابو الحسن! رسول اللہ صلی اللہ علیہ وسلم نے کس حال میں صبح کی ہے؟ انہوں نے کہا: الحمد للہ اب آپ کو افاقہ ہے۔ ابن عباس کہتے ہیں کہ عباس بن عبد المطلب ان کا ہاتھ پکڑ کر ایک طرف لے گئے اور کہا: کیا تمہیں خبر ہے! اللہ کی قسم تم تین دن بعد لاٹھی کے بندے بن جاؤ گے، یعنی دوسروں کے ماتحت ہو گئے۔ اور میں اللہ کی قسم دیکھ رہا ہوں کہ آپ اس مرض میں وفات پا جائیں گے کیونکہ میں جانتا ہوں کہ موت کے وقت بنو عبد المطلب کے چہرے کیسے ہوتے ہیں۔ ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس چلیں اور آپ سے خلافت کے بارے پوچھ لیں۔ اگر ہم میں سے کوئی ہوگا تو ہم اسے جان لیں گے اور اگر ہمارے علاوہ کوئی اور ہوگا تو ہم آپ سے بات کریں کہ آپ ہمارے بارے میں وصیت فرما دیں۔ سیدنا علی رضی اللہ عنہ نے کہا: اللہ کی قسم! اگر ہم نے سوال کیا اور آپ نے ہمیں اس سے منع کر دیا تو لوگ آپ کے بعد کبھی ہمیں اقتدار نہیں دیں گے۔ اللہ کی قسم میں اس بارے میں رسول اللہ صلی اللہ علیہ وسلم سے کبھی سوال نہیں کروں گا۔","",{"k":"صحیح: صحیح بخاری(۴۴۴۷)۔","f":"کسی کی خیریت دریافت کرنا مسنون ہے اور اس کے لیے یہ انداز اختیار کرنا کہ تم نے صبح کس حال میں کی؟ جائز ہے۔ مریض اگر حقیقت حال بتائے گا تو یہ شکوہ نہیں ہوگا۔ اسی طرح کسی دوسرے شخص سے بھی بیمار کا حال دریافت کیا جا سکتا ہے۔\nاس حدیث سے شیعہ کے مذعومہ عقیدہ خلیفہ بلا فصل کی تردید ہوتی ہے۔ اگر سیدنا علی رضی اللہ عنہ خلیفہ بلا فصل ہوتے تو لوگوں کے سامنے ضرور اس کا اظہار کرتے۔","u2":"جناب عبداللہ بن کعب بن مالک انصاری رحمہ اللہ، اور کعب بن مالک رضی اللہ عنہ تو یہ ان تین لوگوں میں سے ایک تھے جن کی توبہ قبول کی گئی تھی، بیان کرتے ہیں کہ سیدنا ابن عباس رضی اللہ عنہ نے اسے خبر دی کہ سیدنا علی بن ابی طالب رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کے پاس سے اس مرض میں نکلے جس میں آپ کی وفات ہوگئی تھی، تو لوگوں نے پوچھا: اے ابو الحسن! رسول اللہ صلی اللہ علیہ وسلم نے کس حال میں صبح کی؟ انہوں نے کہا: الحمد للہ آپ نے افاقہ مرض کی حالت میں صبح کی۔ ابن عباس رضی اللہ عنہ فرماتے ہیں: سیدنا عباس بن عبد المطلب رضی اللہ عنہ نے ان کا ہاتھ پکڑ کر کہا: میں تجھے بتاتا ہوں، اللہ کی قسم! تین دن بعد تمہیں لاٹھی کا بندہ بننا پڑے گا اور اللہ کی قسم! میں تو دیکھ رہا ہوں کہ رسول اللہ صلی اللہ علیہ وسلم اپنے اس مرض میں جلد ہی وفات پا جائیں گے کیونکہ میں عبد المطلب کے بیٹوں کے چہروں کو موت کے وقت پہچان لیتا ہوں، تم ہمارے ساتھ رسول اللہ صلی اللہ علیہ وسلم کے پاس چلو، ہم آپ صلی اللہ علیہ وسلم سے پوچھتے ہیں کہ خلافت کن لوگوں میں ہوگی، اگر یہ ہم میں ہو تو ہمیں اس کا پتا چل جائے گا اور اگر ہمارے علاوہ دوسروں میں ہے تو ہم آپ سے کہیں کہ آپ صلی اللہ علیہ وسلم ہمارے متعلق کچھ وصیت فرما دیں۔ سیدنا علی رضی اللہ عنہ نے فرمایا: اللہ کی قسم! اگر ہم نے اس کے متعلق آپ سے پوچھ لیا اور آپ نے ہمیں اس سے منع کر دیا تو لوگ اس کے بعد ہمیں کبھی بھی (خلافت) نہیں دیں گے، اللہ کی قسم! میں اس کے متعلق رسول اللہ صلی اللہ علیہ وسلم سے کبھی بھی سوال نہیں کروں گا۔"}],[1131,"ابو الزناد رحمہ اللہ سے روایت ہے کہ انہوں نے یہ خط خارجہ بن زید اور آل زید کے سر کردہ لوگوں سے لیا۔ بسم اللہ الرحمن الرحیم۔ اللہ کے بندے امیر المومنین معاویہ کے نام زید بن ثابت کی طرف سے۔ امیر المومنین آپ پر سلام اور اللہ کی رحمت ہو۔ میں اس اللہ کی تعریف کرتا ہوں جس کے سوا کوئی معبود برحق نہیں۔ اما بعد، آپ نے دادا اور بھائیوں کی وراثت کے بارے میں پوچھا ہے (اور پھر پورا خط ذکر کیا) اور ہم اللہ سے ہدایت، حفاظت اور اپنے معاملات میں استقامت کا سوال کرتے ہیں اور اس بات سے اللہ کی پناہ مانگتے ہیں کہ ہم گمراہ ہوں یا جہالت کے مرتکب ہوں یا ایسی ذمہ داری ہم پر پڑے جس کا ہمیں علم نہ ہو۔ والسلام علیک امیر المومنین ورحمتہ اللہ وبرکاتہ ومغفرتہ۔ یہ خط وہیب نے جمعرات کے دن لکھا جبکہ رمضان ۴۲ ہجری کے بارہ دن باقی تھے۔","",{"t":"خط کے آخر میں سلام، کاتب کا نام اور تاریخ لکھنا","k":"حسن: حدیث ۱۱۲۲۔","f":"اس سے معلوم ہوا کہ خط کے آخر میں سلام لکھنا بھی درست ہے، نیز تاریخ اور کاتب کا نام لکھنا بھی جائز بلکہ مسنون ہے تا کہ سند رہے کہ کس نے لکھا ہے۔","u2":"جناب ابن ابی الزناد رحمہ اللہ کہتے ہیں کہ مجھے میرے والد بیان کرتے ہیں کہ انہوں نے یہ خط خارجہ بن زید رحمہ اللہ اور آل زید کے بزرگوں سے حاصل کیا ہے (جس کا مضمون یوں ہے:) بسم اللہ الرحمن الرحیم: یہ خط زید بن ثابت کی طرف سے، اللہ کے بندے امیر المومنین معاویہ رضی اللہ عنہ کے لیے ہے۔ اے امیر المومنین! آپ پر سلام اور اللہ کی رحمت ہو۔ میں آپ کے سامنے اس اللہ کی تعریف کرتا ہوں جس کے سوا کوئی معبود نہیں۔ اما بعد! آپ نے مجھ سے دادا اور بھائیوں کی میراث کے بارے میں پوچھا ہے۔ پھر پورے خط کا ذکر کیا اور (آخر میں کہا کہ) ہم اللہ سے ہدایت، حفاظت اور اپنے تمام معاملات میں استقامت کا سوال کرتے ہیں، اور ہم اللہ تعالی کی پناہ مانگتے ہیں کہ ہم گمراہ ہوں یا جہالت برتیں یا ہم اس چیز کے مکلف نہیں جس کا ہمیں علم نہیں اور سلام ہو آپ پر اے امیر المومنین! اللہ کی رحمت، اور اس کی برکت، اور اس کی مغفرت ہو۔ یہ خط وہیب نے بروز جمعرات ۱۸/ رمضان ۴۲ھ کو لکھا ہے۔"}],[1132,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ انہوں نے سیدنا عمر بن خطاب رضی اللہ عنہ سے سنا، انہیں ایک آدمی نے سلام کہا اور انہوں نے سلام کا جواب دیا، پھر اس آدمی سے پوچھا: تمہارا کیا حال ہے؟ اس نے کہا: میں آپ کے سامنے اللہ کی تعریف کرتا ہوں۔ سیدنا عمر رضی اللہ عنہ نے فرمایا: میں تم سے یہی جواب چاہتا تھا۔","",{"t":"یہ پوچھنا کہ تم کیسے ہو؟","k":"صحیح الإسناد موقوفا ثبت مرفوعا: الموطا(۲/۹۶۱)، ابن المبارک فی الزہد(۲۰۵)، ابن أبی الدنیا فی الشکر(۹۳)، الصحیحہ(۲۹۵۲)۔","f":"مطلب یہ ہے کہ جب کسی سے پوچھا جائے کہ تمہارا کیا حال ہے تو اسے اللہ کا شکر بجا لانا چاہیے۔ اس طرح اسے پوری تفصیل بتانے کی ضرورت نہیں۔","u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ انہوں نے سیدنا عمر بن خطاب رضی اللہ عنہ سے سنا، انہیں ایک آدمی نے سلام کیا تو انہوں نے سلام کا جواب دیا، پھر سیدنا عمر رضی اللہ عنہ نے اس آدمی سے پوچھا: تمہارا کیا حال ہے؟ اس نے کہا: میں آپ کے سامنے اللہ تعالی کی تعریف بیان کرتا ہوں، تو سیدنا عمر رضی اللہ عنہ نے فرمایا: میں تم سے یہی چاہتا تھا۔"}],[1133,"سیدنا جابر بن عبد اللہ رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم سے عرض کیا گیا: آپ نے صبح کس حال میں کی؟ آپ نے فرمایا: \"خیر کے ساتھ صبح ہوئی، میں ایسے لوگوں میں سے ہوں جو نہ کسی جنازے میں حاضر ہوئے نہ کسی مریض کی عیادت کی۔\"\"","",{"t":"جب کسی سے حال دریافت کیا جائے تو کیسے جواب دے؟","k":"حسن لغیرہ: ابن ماجہ(۳۷۱۰)۔","f":"حدیث کا مفہوم یہ ہے کہ ہمارے ہاں ہر طرح کی خیریت ہے نہ کوئی فوت ہوا ہے کہ اس کے جنازے میں جاتے اور نہ کوئی بیمار ہے جس کی عیادت کی ضرورت پیش آتی۔ ہر حال میں اللہ کا شکر ہے۔","u2":"سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم سے پوچھا گیا: آپ نے کس حال میں صبح کی؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"ایسی قوم سے بہتر ہوں جس نے نہ کسی جنازے میں شرکت کی اور نہ ہی کسی مریض کی عیادت کی۔\""}],[1134,"مہاجر رحمہ اللہ سے روایت ہے کہ میں نبی صلی اللہ علیہ وسلم کے صحابہ میں سے ایک بھاری جسامت والے حضرمی صحابی کے پاس بیٹھا کرتا تھا۔ جب انہیں کہا جاتا کہ کس حال میں صبح ہوئی تو وہ جواب دیتے۔ ہم اللہ کے ساتھ شرک نہیں کرتے۔","",{"k":"حسن الإسناد موقوفا۔","f":"ان روایات سے معلوم ہوا کہ دین و ایمان کی سلامتی ہی اصل سلامتی ہے۔ دنیاوی معاملات اور جسمانی صحت ثانوی حیثیت رکھتے ہیں۔ اگر انسان شرک و معصیت سے بچا ہوا ہے تو اسے اللہ کا شکر کرنا چاہیے۔ بیماری جلد یا بہ دیر ختم ہو جائے گی۔","u2":"جناب مہاجر رحمہ اللہ بیان کرتے ہیں کہ میں نبی صلی اللہ علیہ وسلم کے اصحاب میں سے ایک بھاری جسم والے صحابی کے پاس بیٹھا کرتا تھا، جب ان سے پوچھا جاتا کہ تو نے کس حال میں صبح کی؟ تو وہ فرماتے تھے: ہم اللہ کے ساتھ شرک نہیں کرتے۔"}],[1135,"سیف بن وہب سے روایت ہے کہ ابو طفیل نے مجھ سے پوچھا: تمہاری عمر کتنی ہے؟ میں نے کہا: میں تینتیس سال کا ہوں۔ انہوں نے کہا: کیا تمہیں ایک حدیث نہ سناؤں جو میں نے سیدنا حذیفہ بن یمان رضی اللہ عنہ سے سنی ہے؟ قصہ یوں ہے کہ بنو محارب بن خصفہ کے ایک آدمی جنہیں عمرو بن صلیح کہا جاتا تھا اور انہیں شرف صحابیت بھی حاصل تھا۔ ان کی عمر اتنی تھی جتنی آج میری ہے اور میں آج تمہاری عمر کا ہوں۔ ہم سیدنا حذیفہ رضی اللہ عنہ کے پاس مسجد میں آئے اور میں لوگوں کے آخر میں بیٹھ گیا اور عمرو آگے بڑھ کر ان کے سامنے جا کر کھڑے ہوئے اور کہا: اے عبداللہ! آپ نے صبح کس حال میں کی یا کہا: آپ نے شام کس حال میں کی؟ انہوں نے فرمایا: میں اللہ کا شکر ادا کرتا ہوں۔ عمرو نے کہا: آپ کے حوالے سے ہمیں کیا باتیں پہنچ رہی ہیں؟ انہوں نے فرمایا: اے عمرو! تمہیں میرے حوالے سے کیا پہنچا ہے؟ انہوں نے کہا: ایسی احادیث جو میں نے نبی صلی اللہ علیہ وسلم سے نہیں سنیں۔ انہوں نے فرمایا: اللہ کی قسم! اگر میں وہ (سب کچھ) تمہیں بیان کروں جو میں نے سنا ہے تو تم رات ہونے تک بھی میرا انتظار نہ کرو۔ لیکن اے عمرو بن صلیح جب تم دیکھو کہ قیس شام میں برسر اقتدار آگئے ہیں تو بچ کر رہنا۔ اللہ کی قسم! بنو قیس کسی مومن بندے کو نہیں چھوڑیں گے مگر یا تو اسے ڈرائیں گے یا قتل کر دیں گے۔ اللہ کی قسم! ان پر ایک زمانہ آئے گا کہ ہر طرف ان کا قبضہ ہوگا۔ انہوں نے کہا: اللہ آپ پر رحم کرے آپ اپنی قوم کی کیا مدد کریں گے؟ انہوں نے فرمایا: یہ مجھ پر رہا (کہ میں نے کیا کرنا ہے؟) پھر وہ بیٹھ گئے۔","",{"k":"ضعیف: جامع معمر(۱۹۸۸۹)، الحاکم(۴/۵۱۶) مطولاً، مسند الطیالسی(۴۲۱)، ابن ابی شیبہ(۳۷۴۰۰)، مسند احمد(۲۳۳۱۶)، مسند الشامیین(۱۹۵۲) مختصراً۔ فالأثر صحیح۔","f":"اس روایت کی سند ضعیف ہے، تاہم اس کے بعد آنے والے الفاظ دیگر شواہد کی بنا پر صحیح ثابت ہیں۔\nسیدنا حذیفہ رضی اللہ عنہ کا مطلب فتنوں کی نشان دہی تھی جو مستقبل میں اس امت کو پیش آنے والے تھے۔ ان فتنوں کے دور کے حوالے سے جب سیدنا حذیفہ رضی اللہ عنہ سے پوچھا گیا تو انہوں نے فرمایا: اس وقت کچھ کہنا قبل از وقت ہے اس وقت دیکھیں گے کہ کیا کرنا ہے۔","u2":"جناب سیف بن وہیب رحمہ اللہ کہتے ہیں کہ مجھے ابو طفیل رضی اللہ عنہ نے کہا: کہ تیری عمر کتنی ہے؟ میں نے عرض کیا: تینتیس سال کا ہوں، پھر انہوں نے کہا: کیا میں تجھے ایک ایسی حدیث نہ بیان کروں جو میں نے حذیفہ بن یمان رضی اللہ عنہ سے سنی ہے؟ خصفہ میں سے ایک شخص تھا جسے عمرو بن صلیع کہا جاتا تھا اور اسے نبی صلی اللہ علیہ وسلم کی صحبت حاصل تھی اور میری عمر اس دن تینتیس ہی تھی جتنی آج تمہاری عمر ہے۔ ہم دونوں مسجد میں سیدنا حذیفہ رضی اللہ عنہ کے پاس آئے، میں لوگوں کے اخیر میں بیٹھ گیا اور عمرو رضی اللہ عنہ ان کے سامنے کھڑے ہو گئے اور کہا: اے اللہ کے بندے! آپ نے کس حال میں صبح کی؟ یا پوچھا: کس حال میں شام کی؟ انہوں نے کہا: میں اللہ کی تعریف بیان کرتا ہوں، پھر عمرو رضی اللہ عنہ نے کہا: یہ احادیث کیسی ہیں جو تمہاری طرف سے ہمارے پاس پہنچتی ہیں؟ سیدنا حذیفہ رضی اللہ عنہ نے فرمایا: آپ کو میری طرف سے کیا بات پہنچی ہے، اے عمرو بن صلیع؟ انہوں نے کہا: کچھ ایسی احادیث ہیں جنہیں میں نے نہیں سنا، سیدنا حذیفہ رضی اللہ عنہ نے فرمایا: اللہ کی قسم! اگر میں تم سے وہ احادیث بیان کروں جو میں نے سنی ہیں تو تم رات چھا جانے تک میرا انتظار نہ کرو (بلکہ مجھے قتل کر دو گے) لیکن اے عمرو بن صلیع! (ایک بات یاد رکھو) جب تو قبیلہ قیس کو دیکھے کہ وہ ملک شام کے والی بن گئے ہیں تو بچ کے رہنا، اللہ کی قسم! قیس اللہ کے ہر مومن بندے کو خوفزدہ کر کے یا پھر اسے قتل کر کے ہی چھوڑیں گے، اللہ کی قسم! ان پر ایک ایسا زمانہ ضرور آئے گا کہ وہ ہر جگہ پر قبضہ کریں گے۔ عمرو بن صلیع نے کہا: اللہ تعالی آپ پر رحم کرے، آپ کی اس دن اپنی قوم کے لیے کیا مدد ہو گی؟ انہوں نے فرمایا: یہ میرا کام ہے، پھر یہ فرما کر وہ بیٹھ گئے۔"}],[1136,"عبد الرحمن بن ابی عمرہ انصاری رحمہ اللہ سے روایت ہے، انہوں نے کہا کہ سیدنا ابو سعید خدری رضی اللہ عنہ کو کسی جنازے کی اطلاع دی گئی تو وہ لیٹ ہو گئے یہاں تک کہ لوگ انتظار میں اپنی اپنی جگہ پر بیٹھ گئے، پھر وہ بعد میں آئے جب لوگوں نے انہیں دیکھا تو جلدی سے آگے سے ہٹ گئے اور کئی لوگ کھڑے ہو گئے تا کہ وہ انہیں اپنی جگہ پر بٹھائیں۔ انہوں نے فرمایا: میں نہیں بیٹھوں گا۔ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: بہترین مجلس وہ ہے جو کشادہ ہو۔ \"پھر ایک طرف ہو کر وسیع مجلس میں بیٹھ گئے۔","",{"t":"بہترین مجلس وہ ہے جو کشادہ ہو","k":"صحیح: مسند احمد(۱۱۱۳۷)، ابوداؤد(۴۸۲۰)۔","f":"رسول اکرم صلی اللہ علیہ وسلم نے کسی آدمی کو مجلس سے اس کی جگہ سے اٹھا کر خود بیٹھنے سے منع کیا ہے۔ سیدنا ابن عمر رضی اللہ عنہما کے لیے اگر کوئی آدمی از خود اٹھتا تو بھی اس کی جگہ پر نہیں بیٹھتے تھے۔ سیدنا ابو سعید رضی اللہ عنہ نے بھی اس انداز کو نا پسند فرمایا اور حکم دیا کہ مجلس کو وسیع کر لیا جائے اور پھر خود مجلس وسیع کر کے ایک طرف ہو کر بیٹھ گئے۔","u2":"جناب عبد الرحمن بن ابی عمرہ انصاری رحمہ اللہ بیان کرتے ہیں کہ سیدنا ابو سعید خدری رضی اللہ عنہ کو ایک جنازے کی اطلاع دی گئی، راوی کہتا ہے، وہ پیچھے رہ گئے۔ یہاں تک لوگ اپنی اپنی جگہ پر بیٹھ چکے تھے پھر اس کے ساتھ وہ تشریف لائے، جب لوگوں نے انہیں آتا ہوا دیکھا تو جلدی سے ان کے لیے ہٹ گئے اور ان میں سے بعض اپنی جگہ سے کھڑے ہو گئے تا کہ وہ ان کی جگہ پر بیٹھ جائیں۔ سیدنا ابو سعید رضی اللہ عنہ نے فرمایا: نہیں، بلاشبہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا ہے: “بہترین مجلسیں وہ ہیں جو کشادہ ہوں۔” پھر وہ ایک طرف ہٹ کر ایک کشادہ مجلس میں بیٹھ گئے۔"}],[1137,"منقذ بن سفیان رحمہ اللہ سے روایت ہے کہ سیدنا عبداللہ بن عمر رضی اللہ عنہما اکثر و بیشتر قبلہ رخ ہو کر بیٹھتے، چنانچہ یزید بن عبد اللہ بن قسیط نے طلوع شمس کے بعد سورہ سجدہ پڑھی تو سجدہ کیا اور انہوں نے بھی سجدہ کیا سوائے عبد اللہ بن عمر رضی اللہ عنہما کے۔ پھر جب سورج اچھی طرح طلوع ہو گیا تو انہوں نے اپنی چادر کھولی، پھر سجدہ کیا اور کہا: کیا تم نے اپنے ساتھیوں کا سجدہ دیکھا؟ انہوں نے ایسے وقت میں سجدہ کیا جب نماز کا وقت نہیں تھا۔","",{"t":"باب: استقبال القبلة قبلہ رخ ہونے کا بیان","k":"ضعیف الإسناد موقوفا: مصنف ابن ابی شیبہ(۲/۱۶)، ضعیف ابی داؤد(۲۰۴)۔ من طرق، وروی مرفوعا ضعیف۔","f":"اس روایت کی سند ضعیف ہے۔ اس میں سفیان بن منقد راوی مجہول ہے۔","u2":"جناب سفیان بن منقذ رحمہ اللہ اپنے والد سے روایت کرتے ہیں کہ سیدنا عبد اللہ بن عمر رضی اللہ عنہما اکثر قبلہ رخ بیٹھتے تھے، ایک دفعہ یزید بن عبد اللہ بن قسیط رحمہ اللہ نے سورج طلوع ہونے کے بعد آیت سجدہ کی تلاوت کی، انہوں نے اور باقی سب لوگوں نے سجدہ کیا سوائے سیدنا عبد اللہ بن عمر رضی اللہ عنہما کے، پھر جب سورج طلوع ہو گیا تو سیدنا ابن عمر رضی اللہ عنہما نے اپنا گوٹ بند کھولا پھر سجدہ کیا اور فرمایا: کیا تو نے اپنے ساتھیوں کا سجدہ نہیں دیکھا؟ بے شک انہوں نے ایسے وقت میں سجدہ کیا جب نماز کا وقت نہیں تھا۔"}],[1138,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے وہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں (کہ آپ نے فرمایا: \"جب تم میں سے کوئی اپنی مجلس سے اٹھ کر جائے اور پھر واپس آئے تو وہ اس جگہ کا زیادہ مستحق ہے۔\"","",{"t":"جب کوئی شخص مجلس سے اٹھ کر جائے اور پھر اپنی جگہ پر واپس آئے تو","k":"صحیح: صحیح مسلم(۲۱۷۹)، ابوداؤد(۴۸۵۳)، ابن ماجہ(۳۷۱۷)۔","f":"کوئی شخص اگر مجلس سے اٹھ کر واپس آنے کی نیت اور ارادے سے جاتا ہے تو وہ اپنی جگہ پر بیٹھنے کا زیادہ مستحق ہے۔ اسی طرح کلاس روم اور درس و تدریس میں بیٹھا شخص بھی اپنی جگہ کا زیادہ مستحق ہے۔ تاہم مستقل جگہ اپنے لیے خاص کر لینا اور دوسروں کو، نہ ہوتے ہوئے بھی اس کی جگہ خالی رکھنے پر مجبور کرنا مناسب نہیں۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: “جب کوئی تم میں سے اپنی جگہ سے اٹھ کر جائے پھر واپس اسی جگہ لوٹ آئے تو وہی اس جگہ کا زیادہ مستحق ہے۔”"}],[1139,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے جبکہ ہم بچے تھے۔ آپ نے ہمیں سلام کیا اور مجھے کسی کام کے لیے بھیجا اور راستے میں بیٹھ کر میرا انتظار فرماتے رہے یہاں تک کہ میں واپس آگیا۔ حضرت انس کہتے ہیں کہ میں (اپنی والدہ) ام سلیم کے پاس جانے سے لیٹ ہوگیا تو انہوں نے پوچھا: تم لیٹ کیوں ہوئے؟ میں نے کہا: مجھے نبی صلی اللہ علیہ وسلم نے کام بھیجا تھا۔ انہوں نے کہا: کس کام بھیجا تھا؟ میں نے کہا: وہ راز دارانہ کام تھا۔ انہوں نے کہا: پھر رسول اللہ صلی اللہ علیہ وسلم کے راز کی حفاظت کرنا۔","",{"t":"راستے پر بیٹھنے کا شرعی حکم","k":"صحیح: صحیح مسلم(۲۴۸۲)، ابوداؤد(۵۲۰۳)۔","f":"اس سے معلوم ہوا کہ ضرورت کے تحت راستوں پر بیٹھنا جائز ہے، تاہم راستے کا حق ادا کرنا ضروری ہے جو دوسری احادیث میں بتایا گیا ہے کہ سلام کا جواب دینا نگاہ کو پست رکھنا اور بھولے کو راستہ بتانا وغیرہ۔\nبچوں کو اخلاقیات کی تعلیم دینا مستحب ہے جیسا کہ سیدہ ام سلیم رضی اللہ عنہا نے سیدنا انس رضی اللہ عنہ کو رسول اکرم صلی اللہ علیہ وسلم کا راز فاش نہ کرنے کا حکم دیا۔","u2":"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے، ہم اس وقت چھوٹے بچے تھے، آپ صلی اللہ علیہ وسلم نے ہمیں سلام کہا اور مجھے ایک کام کے لیے بھیج دیا اور خود راستے میں بیٹھ کر میرا انتظار کرنے لگے یہاں تک کہ میں آپ صلی اللہ علیہ وسلم کے پاس واپس لوٹ آیا، سیدنا انس رضی اللہ عنہ کہتے ہیں: یوں میں نے اپنی والدہ ام سلیم رضی اللہ عنہا کے پاس پہنچنے میں دیر کر دی تو انہوں نے پوچھا: تجھے کس نے روک لیا تھا؟ میں نے کہا: مجھے نبی صلی اللہ علیہ وسلم نے کسی کام بھیجا تھا، انہوں نے کہا: وہ کیا تھا؟ میں نے کہا: وہ ایک راز ہے، انہوں نے کہا: پھر میری والدہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم کے راز کی حفاظت کر۔"}],[1140,"سیدنا ابن عمر رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کوئی کسی شخص کو اس کی جگہ سے اٹھا کر خود وہاں نہ بیٹھے بلکہ جگہ بنا لیا کرو اور کھل جایا کرو۔\"","",{"t":"مجلس کو کشادہ کرنا","k":"صحیح: صحیح بخاری(۶۲۷۰)، صحیح مسلم(۲۱۷۷)، ترمذی(۲۷۴۹)۔","f":"اس سے مراد عام محفل ہے، تاہم اگر کسی کی خاص مجلس ہے اور وہ کسی شخص کو اس میں شریک نہیں کرنا چاہتے تو اسے اٹھایا جاسکتا ہے۔ عام مجلسوں میں وسعت اختیار کر کے آنے والے کو جگہ دینی چاہیے اور دائرہ بڑھا لینا چاہیے۔ اس طرح آنے والے کو بھی چاہیے کہ جہاں جگہ ملے بیٹھ جائے۔ لوگوں کو تنگ نہ کرے۔","u2":"سیدنا ابن عمر رضی اللہ عنہما بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا: “تم میں سے کوئی شخص کسی کو اس کی جگہ سے ہر گز نہ اٹھائے کہ پھر خود اس جگہ بیٹھے، لیکن کشادہ ہو جایا کرو اور کھل جایا کرو۔”"}],[1141,"سیدنا جابر بن سمرہ رضی اللہ عنہ سے روایت ہے کہ جب ہم نبی صلی اللہ علیہ وسلم کے پاس آیا کرتے تو ہمیں جہاں جگہ مل جاتی ہم وہیں بیٹھ جاتے۔","",{"t":"آدمی کو جہاں جگہ ملے بیٹھ جائے","k":"صحیح: ابوداؤد(۴۸۲۵)، ترمذی(۲۷۲۵)۔","f":"کئی لوگوں کی عادت ہوتی ہے کہ آتے دیر سے ہیں لیکن بیٹھنا آگے چاہتے ہیں جیسا کہ جلسہ گاہ میں عموماً ہوتا ہے۔ ایسا کرنا آداب کے منافی ہے۔","u2":"سیدنا جابر بن سمرہ رضی اللہ عنہ بیان کرتے ہیں کہ جب ہم رسول اللہ صلی اللہ علیہ وسلم کی مجلس میں آتے تو ہم میں سے ہر کوئی جہاں اسے جگہ ملتی وہیں بیٹھ جاتا تھا۔"}],[1142,"سیدنا عبد اللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: \"کسی آدمی کے لیے حلال نہیں کہ وہ (مل کر بیٹھے ہوئے) دو آدمیوں کے درمیان (بیٹھ کر) جدائی ڈالے۔ مگر ان کی اجازت سے بیٹھ سکتا ہے۔\"","",{"t":"دو آدمیوں کے درمیان جدائی نہ ڈالی جائے","k":"حسن: ابوداؤد(۴۸۴۵)، ترمذی(۲۷۵۲)۔","f":"دو آدمی اگر اکٹھے بیٹھے ہوں تو ان کے درمیان آکر گھس جانا ادب کے منافی ہے۔ ممکن ہے دو کوئی خفیہ بات کر رہے ہوں یا ایک ساتھ بیٹھنا چاہتے ہوں۔","u2":"سیدنا عبد اللہ بن عمرو رضی اللہ عنہما بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: “کسی شخص کے لیے یہ جائز نہیں کہ وہ دو (بیٹھے ہوئے) آدمیوں کے درمیان ان کی اجازت کے بغیر جدائی ڈالے (اور خود وہاں بیٹھے)۔”"}],[1143,"سیدنا ابن عباس رضی اللہ عنہما سے روایت ہے کہ جب سیدنا عمر رضی اللہ عنہ کو زخمی کیا گیا تو انہیں اٹھا کر گھر لے جانے والوں میں، میں بھی تھا۔ انہوں نے مجھ سے فرمایا: میرے بھتیجے جا کر دیکھو کہ کس نے مجھے زخمی کیا ہے اور میرے ساتھ اور کون زخمی ہوا۔ چنانچہ میں گیا اور واپس آیا تو گھر بھرا ہوا تھا۔ میں نے لوگوں کی گردنیں پھلانگنا نا پسند کیا، اور میں کم عمر تھا، لہٰذا بیٹھ گیا۔ سیدنا عمر رضی اللہ عنہ جب کسی کو کام بھیجتے تو اس کو اس بات کی اطلاع کا حکم فرماتے۔ وہ کپڑا لپیٹے ہوئے تھے کہ سیدنا کعب رضی اللہ عنہ آگئے اور انہوں نے کہا: اللہ کی قسم! اگر امیر المومنین دعا کریں تو اللہ تعالی انہیں ضرور زندگی دے گا اور اس امت کے لیے انہیں ضرور بلندی عطا کرے گا یہاں تک کہ وہ ایسا ایسا کریں گے۔ یہاں تک کہ انہوں نے منافقین کا ذکر کیا اور بعض کا نام اور بعض کے بارے میں اشارہ کیا۔ میں نے کہا: میں آپ کی بات انہیں بتاؤں؟ انہوں نے کہا: میرے بتانے کا مقصد ہی یہ ہے کہ تم انہیں یہ بات پہنچاؤ۔ میں ہمت کر کے اٹھا اور لوگوں کی گردنیں پھاندتا ہوا سیدنا عمر رضی اللہ عنہ کے سرہانے جا بیٹھا۔ میں نے کہا: آپ نے مجھے فلاں کام بھیجا تھا اور آپ کے ساتھ فلاں فلاں تیرہ آدمی زخمی ہوئے ہیں اور کلیب جزار کو بھی نیزہ لگا ہے جبکہ وہ پتھر کے حوض کے پاس وضو کر رہے تھے۔ اور کعب اللہ کی قسم اٹھا کر اس طرح کہہ رہے ہیں۔ انہوں نے فرمایا: کعب کو میرے پاس بلاؤ۔ چنانچہ انہیں بلایا گیا تو سیدنا عمر رضی اللہ عنہ نے فرمایا: تم کیا کہتے ہو؟ انہوں نے کہا: میں یہ کہتا ہوں۔ انہوں نے فرمایا: نہیں اللہ کی قسم میں دعا نہیں کروں گا لیکن عمر بد بخت ہے اگر اللہ نے اس کی مغفرت نہ کی۔","",{"t":"گردنیں پھاند کر صدر مجلس کے پاس بیٹھنا","k":"ضعیف الإسناد موقوفا: تاریخ المدینہ(۳/۹۰۹)، تاریخ دمشق(۴۴/۴۲۱)۔","f":"اس روایت کی سند ضعیف ہے، اس میں ابو عامر صالح بن رستم المزنی راوی ضعیف ہے۔ تاہم کسی شدید ضرورت کے تحت ایسا کرنا جائز ہے کیونکہ ضرورتیں نا جائز کاموں کو بھی مباح کر دیتی ہیں۔","u2":"سیدنا ابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ جب سیدنا عمر رضی اللہ عنہ کو زخمی کیا گیا تو میں ان لوگوں میں سے تھا جنہوں نے ان کو زخمی حالت میں اٹھا کر ان کے گھر پہنچایا تھا، سیدنا عمر رضی اللہ عنہ نے مجھے فرمایا: اے میرے بھتیجے! جا کر دیکھو کس نے مجھے تکلیف پہنچائی ہے، اور میرے ساتھ دوسرے کن اشخاص کو تکلیف پہنچی ہے، میں گیا پھر واپس آیا تا کہ انہیں بتاؤں تو دیکھا کہ سارا گھر لوگوں سے بھرا ہوا ہے، میں نے مناسب نہ جانا کہ لوگوں کی گردنیں پھلانگ کر آگے بڑھوں اور میں ویسے بھی کم عمر تھا اس لیے میں پیچھے ہی بیٹھ گیا، سیدنا عمر رضی اللہ عنہ جب کسی کو کسی کام کے لیے بھیجتے تو اسے اس بات کی اطلاع کرنے کا حکم فرماتے تھے، اس وقت وہ کپڑا اوڑھے ہوئے تھے، اتنے میں سیدنا کعب رحمہ اللہ آئے اور عرض کیا: اللہ کی قسم! اگر امیر المومنین دعا فرما دیں تو اللہ تعالی ان کو ضرور باقی رکھے گا اور اس امت کے لیے انہیں ضرور بلندی عطا فرمائے گا یہاں تک کہ وہ اس میں ایسے ایسے کام کر جائیں گے حتی کہ سیدنا کعب رحمہ اللہ نے اپنے اس بیان میں منافقوں کا بھی ذکر کیا، میں نے کہا: کیا جو کچھ آپ کہہ رہے ہیں میں یہ امیر المومنین کو پہنچا دوں؟ انہوں نے کہا: میں نے اسی لیے یہ باتیں کی ہیں تا کہ تم انہیں پہنچا دو، میں نے جرات کی، کھڑا ہوا اور لوگوں کی گردنیں پھلانگتا ہوا ان کے سرہانے کے پاس جا بیٹھا اور کہا: آپ نے مجھے فلاں کام کے لیے بھیجا تھا، آپ کے ساتھ تیرہ آدمی زخمی ہوئے ہیں اور کلیب جزار رحمہ اللہ بھی زخمی ہوئے ہیں وہ پتھر کے حوض کے پاس وضو کر رہے تھے اور سیدنا کعب رحمہ اللہ وہ اس طرح اللہ کی قسم کھا رہے ہیں، سیدنا عمر رضی اللہ عنہ نے فرمایا: کعب رحمہ اللہ کو بلاؤ، لہٰذا انہیں بلایا گیا تو آپ نے فرمایا: تم کیا کہتے ہو؟ انہوں نے کہا: میں اس اس طرح کہتا ہوں، آپ نے فرمایا: نہیں، اللہ کی قسم! میں دعا نہیں کروں گا، لیکن عمر رضی اللہ عنہ بد بخت ہے اگر اللہ تعالی نے اس کی مغفرت نہ فرمائی۔"}],[1144,"امام شعبی رحمہ اللہ سے روایت ہے کہ ایک شخص سیدنا عبداللہ بن عمرو رضی اللہ عنہما کے پاس آیا۔ لوگ بھی موجود تھے۔ وہ لوگوں کی گردنیں پھاند کر آگے بڑھنے لگا تو لوگوں نے اسے روک دیا۔ سیدنا عبداللہ رضی اللہ عنہما نے فرمایا: اس آدمی کو آنے دو۔ وہ آگے بڑھا اور ان کے پاس بیٹھ کر کہا: مجھے کوئی حدیث بتائیں جو آپ نے رسول اللہ صلی اللہ علیہ وسلم سے سنی ہو۔ انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"مسلمان وہ ہے جس کی زبان اور ہاتھ سے دوسرے مسلمان محفوظ ہوں اور مہاجر وہ ہے جو ان چیزوں کو چھوڑ دے جن سے اللہ نے منع کیا ہے۔\"","",{"k":"صحیح: صحیح بخاری(۱۰)، صحیح مسلم(۴۰)، ابوداؤد(۲۴۸۱)۔","f":"اس سے معلوم ہوا کہ کوئی شخص کسی خاص ضرورت کے لیے اگر صدر مجلس کے پاس جانا چاہے تو لوگوں کے درمیان سے گزر کر جاسکتا ہے، نیز اس سے معلوم ہوا کہ قرآن و حدیث کے طالب علم کی عزت و توقیر کرنی چاہیے۔ اگر کوئی شخص دینی مسئلہ دریافت کرتا ہے تو باقی گفتگو ختم کر کے اسے مسئلہ بتانا چاہیے۔","u2":"امام شعبی رحمہ اللہ بیان کرتے ہیں کہ ایک آدمی سیدنا عبد اللہ بن عمرو رضی اللہ عنہما کے پاس آیا، اس وقت ان کے پاس کچھ لوگ بھی بیٹھے ہوئے تھے، وہ آدمی گردنیں پھلانگ کر ان کی طرف آنے لگا تو لوگوں نے اسے روکا، اس پر سیدنا عبد اللہ بن عمرو رضی اللہ عنہما نے کہا: اس آدمی کو چھوڑ دو، چنانچہ وہ آپ کے پاس آ کر بیٹھ گیا اور کہا: مجھے ایسی چیز بتلائیے جو آپ نے رسول کریم صلی اللہ علیہ وسلم سے سنی ہو؟ آپ رضی اللہ عنہما نے فرمایا: میں نے نبی صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا کہ مسلمان وہ ہے جس کی زبان اور ہاتھ سے دوسرے مسلمان محفوظ ہوں اور مہاجر وہ ہے جو ان چیزوں کو چھوڑ دے جن سے اللہ تعالی نے منع فرمایا ہے۔"}],[1145,"سیدنا ابن عباس رضی اللہ عنہما سے روایت ہے، انہوں نے فرمایا: میرے نزدیک لوگوں میں سب سے زیادہ معزز میرا ہم نشین ہے۔","",{"t":"سب سے معزز آدمی کا ہم نشین ہے","k":"صحیح: التاریخ الکبیر(۶/۳۹۳)، ابن المبارک فی الزہد(۶۶۷)، مکارم الأخلاق(۷۱۳)۔","f":"اس سے معلوم ہوا ہم نشین کی عزت اور توقیر کرنا لازم ہے۔ اس سے مراد اچھا دوست اور ہم نشیں ہے جو آدمی کو اچھائی کی دعوت دے۔ برے ساتھی کے ساتھ کی تعقیل اور تکریم مقصود نہیں۔","u2":"سیدنا عبد اللہ بن عباس رضی اللہ عنہما فرماتے ہیں: میرے نزدیک لوگوں میں سب سے زیادہ معزز میرا ہم نشین ہے۔"}],[1146,"سیدنا ابن عباس رضی اللہ عنہما سے روایت ہے، انہوں نے فرمایا: میرے نزدیک سب سے زیادہ معزز میرا ہم نشین ہے اگر چہ وہ لوگوں کی گردنیں پھاند کر آئے یہاں تک کہ میرے پاس آکر بیٹھ جائے۔","",{"k":"ضعیف: روضۃ العقلاء(۱/۱۱۷)، شعب الإیمان(۹۱۲۲)، الفقیہ والمتفقہ(۲/۲۲۶)۔","f":"اس روایت کی سند ضعیف ہے۔ اس میں عبداللہ بن مؤمل راوی ضعیف ہے۔","u2":"سیدنا ابن عباس رضی اللہ عنہما فرماتے ہیں: میرے نزدیک لوگوں میں سے سب سے زیادہ معزز میرا ہم نشین ہے اور وہ لوگوں کی گردنیں پھلانگ کر بھی میرے ساتھ آ کر بیٹھ جائے۔"}],[1147,"کثیر بن مرہ رحمہ اللہ سے روایت ہے کہ میں جمعہ کے روز مسجد میں داخل ہوا تو میں نے دیکھا کہ سیدنا عوف بن مالک اشجعی رضی اللہ عنہ ایک حلقہ میں تشریف فرما ہیں اور انہوں نے اپنے پاؤں سامنے پھیلائے ہوئے ہیں۔ جب انہوں نے مجھے دیکھا تو پاؤں اکٹھے کر لیے، پھر مجھ سے فرمایا: تمہیں معلوم ہے کہ میں نے پاؤں کیوں پھیلائے ہوئے تھے؟ اس لیے کہ کوئی نیک آدمی آکر بیٹھ جائے۔","",{"t":"کیا آدمی اپنے ہم نشیں کے سامنے پاؤں پھیلا سکتا ہے","k":"حسن۔","f":"اس سے معلوم ہوا کہ اچھا ہم نشین تلاش کرنا چاہیے اور کسی مجلس میں اس لیے جگہ روکنا کہ کوئی اچھا آدمی بیٹھے تو ایسا کرنا جائز ہے، نیز ایسا معاملہ جس کے بارے میں کسی کے دل میں ملال آنے کا اندیشہ ہو یا وہ اس کو برا تصور کر سکتا ہو تو اس کی قبل از وقت وضاحت کر دینا مناسب ہے۔","u2":"جناب کثیر بن مرہ رحمہ اللہ بیان کرتے ہیں کہ میں جمعہ کے دن مسجد میں داخل ہوا تو میں نے عوف بن مالک اشجعی رضی اللہ عنہ کو حلقے میں بیٹھا ہوا پایا، وہ اپنے پاؤں آگے پھیلائے ہوئے تھے، جب انہوں نے مجھے دیکھا تو اپنے پاؤں سمیٹ لیے پھر مجھ سے فرمایا: کیا تم جانتے ہو کہ میں نے کس لیے اپنے پاؤں پھیلائے ہیں؟ تاکہ کوئی نیک آدمی آ کر (اس جگہ) بیٹھے۔"}],[1148,"حارث بن عمرو سہمی بیان کرتے ہیں کہ میں نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا جبکہ آپ منی یا عرفات میں تھے۔ لوگوں نے آپ کو گھیر رکھا تھا۔ دیہاتی لوگ آرہے تھے، جب وہ آپ کا چہرہ مبارک دیکھتے تو کہتے: یہ مبارک چہرہ ہے۔ میں نے عرض کیا: اللہ کے رسول! میرے لیے استغفار فرما دیں۔ آپ نے فرمایا: \"اے اللہ! ہمیں بخش دے۔\" میں گھوم کر پھر آیا اور عرض کیا: اللہ کے رسول! میری مغفرت کی دعا کریں۔ آپ نے فرمایا: \"اے اللہ ہمیں بخش دے۔\" پھر آپ تھوکنے لگے تو ہاتھ منہ کے آگے رکھ کر ہاتھ کے ذریعے تھوک پھینکا اور پھر جوتے کے ذریعے مل دیا۔ آپ نے ناپسند کیا کہ وہ کسی اور کو لگے۔","",{"t":"مجلس میں بیٹھا ہو تو کہاں تھوکے؟","k":"حسن: الآحاد(۱۲۵۷)، المعجم الکبیر(۲۴/۳)، معرفۃ الصحابہ(۲۰۷۹)، تہذیب الکمال(۵/۲۶۴)، ابوداؤد(۱۷۴۲)۔","f":"مطلب یہ ہے کہ مجلس میں اگر تھوک آجائے تو کسی کے سامنے نہیں تھوکنا چاہیے کیونکہ اس سے بندے کی شخصیت مجروح ہوتی ہے۔ کسی رومال وغیرہ میں تھوک لے اور اگر زمین کچی ہو، فرش وغیرہ نہ ہو تو ہاتھ منہ کے آگے رکھ کر ایک طرف ہو کر تھوک لے اور ہاتھ کے ذریعے زمین پر پھینک کر اس کو جوتے وغیرہ سے مل دے اور اس پر مٹی ڈال دے تا کہ اس کا جرم نظر نہ آئے اور کسی دوسرے آدمی کے کپڑے وغیرہ کو نہ لگے۔\nاستغفار کے حوالے سے آپ نے تنبیہ فرمائی کہ اللہ کی وسیع رحمت کو محدود نہیں کرنا چاہیے کہ انسان صرف اپنے لیے مغفرت طلب کرے بلکہ تمام اہل ایمان کے لیے بخشش مانگنی چاہیے۔\nاگر زمین پختہ اور فرش وغیرہ ہو تو اس پر تھوک پھینکنے کے بجائے کپڑے وغیرہ پر تھوک کر بعد ازاں اسے صاف کر لینا چاہیے۔","u2":"سیدنا حارث بن عمرو السہمی رضی اللہ عنہ بیان کرتے ہیں کہ میں نبی صلی اللہ علیہ وسلم کے پاس آیا، آپ اس وقت منی یا عرفات میں تھے۔ لوگوں نے آپ صلی اللہ علیہ وسلم کو گھیر رکھا تھا۔ اسی اثنا میں دیہاتی لوگ آئے اور آپ صلی اللہ علیہ وسلم کا چہرہ دیکھ کر کہنے لگے: یہ مبارک چہرہ ہے۔ میں نے عرض کیا: یا رسول اللہ! میرے لیے مغفرت طلب کیجئے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “اے اللہ! ہماری مغفرت فرما۔” میں گھوم کر پھر آیا اور عرض کیا: میرے لیے مغفرت طلب کیجئے، آپ صلی اللہ علیہ وسلم نے فرمایا: “اے اللہ! ہماری مغفرت فرما۔” میں گھوم کر پھر آیا اور عرض کیا: میرے لیے مغفرت طلب کیجئے تو آپ صلی اللہ علیہ وسلم نے فرمایا: “اے اللہ! ہماری مغفرت فرما۔” پھر آپ صلی اللہ علیہ وسلم تھوک پھینکنے گئے اور اپنے ہاتھ سے اشارہ کیا پھر اس سے تھوک لے کر اسے اپنے جوتے سے مل دیا، اس بات کو ناپسند جانتے ہوئے کہ وہ آپ صلی اللہ علیہ وسلم کے ارد گرد والوں میں سے کسی پر پڑ جائے۔"}],[1149,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے گھروں کے سامنے تھڑوں پر بیٹھنے سے منع فرمایا تو لوگوں نے کہا: اللہ کے رسول! گھروں کے اندر بیٹھے رہنا ہمارے لیے باعث مشقت ہے۔ آپ نے فرمایا: اگر تمہارا چارہ نہ ہو تو پھر ان مجلسوں کا حق ادا کرو۔ انہوں نے کہا: اللہ کے رسول! ان کا حق کیا ہے؟ آپ نے فرمایا: \"راستہ پوچھنے والے کی راہنمائی کرنا، سلام کا جواب دینا، نگاہوں کو پست رکھنا، نیکی کا حکم دینا اور برائی سے روکنا۔\"","",{"t":"چوپالوں یا تھڑوں پر بیٹھنے کا بیان","k":"صحیح: ابوداؤد(۴۸۱۶)، الصحیحہ(۱۵۶۱)۔","f":"عربوں میں رواج تھا کہ وہ گھروں کے سامنے کھلی جگہ پر گلیوں میں بیٹھ کر گپ شپ کرتے تھے کیونکہ گھروں میں خواتین ہوتی تھیں۔ یہ پیٹھکیں راستوں کے اوپر ہوتیں جس سے گزرنے والی خواتین کے لیے بھی مشکل پیدا ہوتی۔ رسول اکرم صلی اللہ علیہ وسلم نے ان چوراہوں پر بیٹھنے سے منع کیا تو صحابہ کرام نے اپنی مجبوری ظاہر کی کہ گھروں میں ہمارے پاس انتظام نہیں ہے اس لیے ہمیں اس کی اجازت مرحمت فرمائیں تو آپ صلی اللہ علیہ وسلم نے مذکورہ آداب کے ساتھ وہاں مجلسیں جمانے کی اجازت دے دی۔","u2":"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے گھروں کے بیرونی چبوتروں پر بیٹھنے سے منع فرمایا، تو صحابہ نے عرض کیا: یا رسول اللہ! ہم پر اپنے گھروں میں بیٹھنا مشکل ہو جاتا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “پھر اگر تم بیٹھو تو بیٹھنے کا حق ادا کرو۔” صحابہ نے عرض کیا: اے اللہ کے رسول! اس کا حق کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: “(راستہ) پوچھنے والے کی راہنمائی کرنا، سلام کا جواب دینا، نظروں کو جھکائے رکھنا، اچھی باتوں کا حکم دینا اور بری باتوں سے روکنا۔”"}],[1150,"سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: \"راستوں پر بیٹھنے سے بچو۔\" انہوں نے عرض کیا: اللہ کے رسول! ہمارا ان مجلسوں میں بیٹھنے کے سوا کوئی چارہ کار نہیں۔ ہم وہاں بیٹھ کر باتیں کرتے ہیں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اچھا اگر تمہارا اصرار ہے تو پھر راستے کا حق ادا کرو۔\" انہوں نے عرض کیا: اللہ کے رسول! راستے کا کیا حق ہے؟ آپ نے فرمایا: \"نظر کو بچا کر رکھنا، تکلیف دہ چیز راستے سے ہٹا دینا، نیکی کا حکم دینا اور برائی سے روکنا۔\"","",{"k":"صحیح: صحیح بخاری(۲۴۶۵)، صحیح مسلم(۲۱۲۱)، ابوداؤد(۴۸۱۵)۔","f":"عربوں میں رواج تھا کہ وہ گھروں کے سامنے کھلی جگہ پر گلیوں میں بیٹھ کر گپ شپ کرتے تھے کیونکہ گھروں میں خواتین ہوتی تھیں۔ یہ پیٹھکیں راستوں کے اوپر ہوتیں جس سے گزرنے والی خواتین کے لیے بھی مشکل پیدا ہوتی۔ رسول اکرم صلی اللہ علیہ وسلم نے ان چوراہوں پر بیٹھنے سے منع کیا تو صحابہ کرام نے اپنی مجبوری ظاہر کی کہ گھروں میں ہمارے پاس انتظام نہیں ہے اس لیے ہمیں اس کی اجازت مرحمت فرمائیں تو آپ صلی اللہ علیہ وسلم نے مذکورہ آداب کے ساتھ وہاں مجلسیں جمانے کی اجازت دے دی۔","u2":"سیدنا ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا: “راستے میں بیٹھنے سے بچو۔” صحابہ نے عرض کیا: اے اللہ کے رسول! ہمارے لیے ہماری مجلسوں کے بغیر کوئی چارہ نہیں، ہم نے ان میں باتیں کرنی ہوتی ہیں، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “اب جبکہ تم انکار کرتے ہو تو پھر راستے کو اس کا حق دو۔” صحابہ نے عرض کیا: اے اللہ کے رسول! راستے کا حق کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: “نظر کو جھکا کے رکھنا، تکلیف دہ چیز کو ہٹانا، اچھی باتوں کا حکم دینا اور بری باتوں سے روکنا۔”"}]]);
